import { untrack } from "svelte";
import { SvelteSet } from "svelte/reactivity";
import { type FontName } from '../ui/excalidraw-defs'

import type {
    CsAbly, CsClassroom, Student, Classroom,
    CsToasts,
} from './tch-dependencies'

import { 
    logger, helpers, browser, theme, config,
    makeToasts,
} from './tch-dependencies'
import type { Toast } from "../ui/toasts-box.svelte";


export interface TextUi {
    text: string;
    color: string;
    bgColor: string;
    fontName: FontName;
}

interface JoinBtn {
    fa: string;
    color: string;
    bgHover: string;
    disabled: boolean;
    list: string[];
    selection: string;
    act: (id: string) => void; 
}

interface Icons {
    mobile: {
        yes: {
            fa: string;
            color: string;
            bgHover: string;
        };
        no: {
            fa: string;
            color: string;
            bgHover: string;
        }
    }
}

export interface AddOrRemove {
    plusColor: string;
    minusColor: string;
    act: (id: string, plus: boolean) => void;
    values: {
        text: string,
        weight: string,
        plus: boolean,
    }[];
}

export interface StudentUi {
    model: Student;
    aliases: string[];
    peers: {profileId: string, color: string}[];
    answer: TextUi;
    points: {gain: number, text: string};
    status: string;
    join: JoinBtn[];
    label: TextUi;
    approved: boolean;
    hints: AddOrRemove;
    removes: AddOrRemove;
    adds: AddOrRemove;
    clearCache: boolean;
    approve: () => void;
}

interface ClassroomUi {
    get students(): SvelteSet<StudentUi>;
    get toasts(): CsToasts;
    classroom: Classroom;
    clearCache(stu: StudentUi): void;
    updateAlias(stu: StudentUi, alias: string): void;
    clearAlias(stu: StudentUi): void;
    congrats(stu: StudentUi): void;
    gainPoints(stu: StudentUi, gain: number): void;
    syncWithClassroom(): void;
    syncStudent(stu: StudentUi, count: number): void;
}

export function makeClassroomUi(
    ably: CsAbly,
    toasts: CsToasts,
    classroom: CsClassroom,
) {
    let log = logger.make("ui");

    let students = new SvelteSet<StudentUi>();
    let studentsAsArray: StudentUi[] = [];

    function makeStudentUi(stu: Student): StudentUi {
        log.info(_=>_(`New student '${stu.name}'`));

        return helpers.reactive({
            model: stu,
            peers: [],
            aliases: [],
            answer: {text: "", color: "darkgreen", bgColor: "lightgreen", fontName: "Nunito"},
            points: {gain: 100, text: "+120"},
            status: "",
            join: [{
                fa: "fa-solid fa-mobile-screen bg-green-100",
                color: "green",
                bgHover: "bg-green-200",
                disabled: false,
                list: ["none"],
                selection: "limegreen",
                act: id => console.log(id),
            }, {
                fa: "fa-solid fa-display bg-red-100",
                color: "red",
                bgHover: "bg-red-200",
                disabled: false,
                list: ["n/a"],
                selection: "red",
                act: id => console.log(id),
            }],
            label: {text: stu.name, color: "blue", bgColor: "yellow", fontName: "Excalifont"},
            approved: false,
            hints: {
                plusColor: "lightgreen",
                minusColor: "red",
                act: (id, pm) => console.log(id, pm),
                values: [
                    { text: "Smeh", weight: "700", plus: true },
                    { text: "איתן אושרוב", weight: "400", plus: true },
                ],
            },
            removes: {
                plusColor: "lightgreen",
                minusColor: "red",
                act: (id, pm) => console.log(id, pm),
                values: [
                    { text: "Gosha Smeh", weight: "700", plus: false },
                    { text: "איתן אושרוב", weight: "400", plus: false },
                ],
            },
            adds: {
                plusColor: "lightgreen",
                minusColor: "red",
                act: (id, pm) => console.log(id, pm),
                values: [
                    { text: "Gosha Smeh", weight: "700", plus: true },
                    { text: "איתן אושרוב", weight: "400", plus: true },
                    { text: "Eitan Osherov", weight: "400", plus: true },
                ],
            },
            clearCache: false,
            approve: () => console.log("approved"),
        } satisfies StudentUi);
    }

    function clearCache(stu: StudentUi) {
        let peers = classroom.peersOf(stu.model);
        let deviceIds = classroom.devicesOf(stu.model);
        ably.publish("t2s-clear-cache", {
            deviceIds,
        }, peers);
    }

    function updateAlias(stu: StudentUi, alias: string) {
        let peers = classroom.peersOf(stu.model);
        ably.publish("t2s-set-profile-alias", {
            profileIds: peers,
            alias,
        }, peers);
    }

    function clearAlias(stu: StudentUi) {
        let peers = classroom.peersOf(stu.model);
        ably.publish("t2s-clear-profile-alias", {
            profileIds: peers,
        }, peers);
    }

    function congrats(stu: StudentUi) {
        let peers = classroom.peersOf(stu.model);
        ably.publish("t2s-congrats", {
            message: "Well done!",
        }, peers);
    }

    function gainPoints(stu: StudentUi, gain: number) {
        let peers = classroom.peersOf(stu.model);
        
        ably.publish("t2s-gain-points", {
            points: gain,
        }, peers);
    }

    function syncStudent(ui: StudentUi, count: number) {
        let stu = ui.model;

        function mapColors() {
            let m = (color: string) => theme.map(color);

            let text = (t: TextUi) =>
                [t.color, t.bgColor] = [m(t.color), m(t.bgColor)];

            let aOrR = (list: AddOrRemove) =>
                [list.plusColor, list.minusColor] = 
                [m(list.plusColor), m(list.minusColor)];

            text(ui.label);
            ui.peers.forEach(peer => peer.color = m(peer.color));
            text(ui.answer);
            ui.join.forEach(join => {
                [join.color, join.bgHover] = [m(join.color), m(join.bgHover)];
            });
            aOrR(ui.hints);
            aOrR(ui.removes);
            aOrR(ui.adds);
        }

        function syncPresence() {
            let label = ui.label;

            switch (stu.presence) {
                default:
                    stu.presence satisfies never;
                case "absent":
                    label.bgColor = "bg-gray-100";
                    label.color = "bg-gray-400";
                    break;
                case "out-of-focus":
                    label.bgColor = "bg-red-100";  // "#ffc9c9";
                    label.color = "blue";
                    break;
                case "hello-is-missing":
                    label.bgColor = "#ffec99";
                    label.color = "blue";
                    break;
                case "here":
                    label.bgColor = "bg-green-100"; // "#ebfbee";
                    label.color = "blue";
                    break;
            }
        }

        let answer = stu.studying.answer;

        log.info(_=>_({id: stu.name, answer, count}));
        ui.status = `syncs: ${count}`;

        ui.label.text = stu.name;
        ui.answer.text = answer;
        let yes = answer.toLowerCase() === "yes";

        helpers.assign(ui.answer, {
            text: answer,
            color: yes ? "text-green-800" : "text-red-800",
            bgColor: yes ? "bg-green-200" : "bg-red-200",
        });

        let peers = stu.online.peers.map(peer => ({
            profileId: `${peer.codename}@${peer.appId}`,
            color: peer.isActive ? "text-green-500" : "text-red-500",
        }));

        ui.peers = peers;

        syncPresence();
        untrack(() => mapColors());
    }

    function syncWithClassroom() {
        let current = classroom.students;

        log.info(_=>_({current: current.length}));

        let previous = new Map<Student, StudentUi>(); 

        studentsAsArray.forEach(ui => {
            if (current.includes(ui.model))
                previous.set(ui.model, ui);
            else
                students.delete(ui);
        });

        studentsAsArray = [];

        current.forEach(model => {
            let ui = previous.get(model) || makeStudentUi(model);
            students.add(ui);
            studentsAsArray.push(ui);
        });

//        studentsAsArray.forEach(ui => syncStudent(ui));
    }

    return {
        get students() { return students; },
        get toasts() { return toasts; },
        classroom,
        clearCache,
        updateAlias,
        clearAlias,
        congrats,
        gainPoints,
        syncWithClassroom,
        syncStudent,
    } as const satisfies ClassroomUi;
}