import { onMount } from 'svelte';
import scheduleYaml from './sch-schedule.yaml?raw';

import type { 
    CsToasts,
    SchSchedule, SchLesson, SharedCounter,
    CsFirebase, 
} from './sch-dependencies';

import {
    config, logger, browser, makeToasts,
    makeFirebase, makeSchedule,
    helpers,
} from './sch-dependencies'

interface SchMain {
    get localhost(): boolean;
    schedule: SchSchedule;
    toasts: CsToasts;
    firebase: CsFirebase;
    getSharedCounter(lesson: SchLesson): SharedCounter;
    enroll(lesson: SchLesson, yes: boolean): void;
    getEnrollment(lesson: SchLesson): boolean;
    loadSchedule(): void;
    pushSchedule(): void;
}

export function makeMain(appId: string) {
    let log = logger.make("cs-main");

    log.info(_=>_({
        appId, 
        deviceId: config.deviceId,
        config,
    }));

    let localhost = location.hostname === "localhost";
    let firebase = makeFirebase();
    let toasts = makeToasts();
    let schedule = makeSchedule(firebase, toasts);

    function makeId(lesson: SchLesson) {
        let courseId = lesson.courseId;
        let date = lesson.date.value.replaceAll('/', '-');
        let time = lesson.time.value.replaceAll(':', '-');
        return `${courseId}_${date}_${time}`;
    }

    function getSharedCounter(lesson: SchLesson) {
        let id = makeId(lesson);
        return firebase.getSharedCounter(id);
    }

    function enroll(lesson: SchLesson, yes: boolean) {
        let id = makeId(lesson);
        log.info(_=>_({id}));

        localStorage.setItem(id, yes.toString()); 
        let counter = getSharedCounter(lesson);

        switch (yes) {
            case true:
                counter.increment();
                lesson.whatsappAura = true;
                break;
            case false:
                counter.decrement();
                break;
        }

        lesson.iAmIn = yes;
    }

    function getEnrollment(lesson: SchLesson) {
        let id = makeId(lesson);

        let yes = helpers.getCached(id, () => false);
        log.info(_=>_({id, yes}));

        lesson.iAmIn = yes;
        return yes;
    }

    function loadSchedule() {
        log.info(_=>_());
        schedule.load(scheduleYaml);
    }

    function pushSchedule() {
        log.info(_=>_());
        schedule.pushToDb();
    }

    onMount(() => {
        toasts.push("להרשמה ללחוץ על סוויטץ' ולהיכנס לקבוצת הואטסאפ", {
            severity: 'success',
            timeout: 5_000
        });
    })

    return {
        get localhost() { return localhost; },
        schedule,
        toasts,
        firebase,
        getSharedCounter,
        enroll,
        getEnrollment,
        loadSchedule,
        pushSchedule,
    } satisfies SchMain;
}
