<script lang="ts">
    import { assert } from './../cs-dependencies';

    type Area = [number, number, number, number, string];

    interface PadLayout {
        question: Area;
        answers: Area[];
    };

    type LayoutName = "a-b" | "a-b-c" | "a-b-c-d"

    let qTailwind = "bg-yellow-100 text-3xl font-bold";
    let aTailwind = "text-4xl font-bold";

    let layouts: Record<LayoutName, PadLayout> = {
        "a-b": {
            question: [5, 0, 90, 25, `${qTailwind}`], 
            answers: [
                [10, 35, 30, 15, `bg-orange-200 ${aTailwind}`],
                [60, 35, 30, 15, `bg-pink-200 ${aTailwind}`],
            ]
        },
        "a-b-c": {
            question: [5, 5, 90, 15, `${qTailwind}`],
            answers: [
                [10, 35, 30, 15, `bg-orange-200 ${aTailwind}`],
                [60, 35, 30, 15, `bg-pink-200 ${aTailwind}`],
                [10, 70, 30, 15, `bg-gray-200 ${aTailwind}`],
            ]
        },
        "a-b-c-d": {
            question: [5, 5, 90, 15, `${qTailwind}`],
            answers: [
                [10, 35, 30, 15, `bg-orange-200 ${aTailwind}`], 
                [60, 35, 30, 15, `bg-pink-200 ${aTailwind}`],
                [10, 70, 30, 15, `bg-gray-200 ${aTailwind}`],
                [60, 70, 30, 15, `bg-indigo-200 ${aTailwind}`], 
            ]
        },
    };

    let num2layout = new Map<number, PadLayout>([
        [2, layouts["a-b"]],
        [3, layouts["a-b-c"]],
        [4, layouts["a-b-c-d"]],
    ]);

    type OnClick = (answer: string) => void;

    interface Props {
        question: string;
        answers: string[];
        act: OnClick;
        answered: string;
    }

    let {question, answers, act, answered}: Props = $props();

    let layout = $derived(num2layout.get(answers.length)!);
    assert(() => !!layout);

    let p = (n: number) => `${n}%`;

    let itsMe = $state("");

    function answer(value: string) {
        if (answered) return;
        
        itsMe = value;
        act(value);
    }
</script>

{#snippet Elem(value: string, area: Area, act: OnClick)}
    <div class="elem {area[4]}"
        style:--left={p(area[0])}
        style:--top={p(area[1])}
        style:--width={p(area[2])}
        style:--height={p(area[3])}
        onclick={() => act(value)}
        class:disabled={answered.length > 0}
        class:itsMe={answered === value}
    >
        <span class="value">
            {value}
        </span>
    </div>
{/snippet}


{#snippet Question()}
    {#if question.length > 0}
    {@render Elem(question, layout.question, () => {})}
    {/if}
{/snippet}

{#snippet Answer(ans: string, indx: number)}
    {@const area = layout.answers[indx]}
    <div>
        {@render Elem(ans, area, answer)}
    </div>
{/snippet}

<div class="pad">
    {@render Question()}
    {#each answers as ans, indx}
        {@render Answer(ans, indx)}
    {/each}
</div>

<style>
.pad {
    position: relative;
    width: 100%;
    height: 100%;
}
.elem {
    position: absolute;
    left: var(--left);
    top: var(--top);
    width: var(--width);
    height: var(--height);
    text-align: center;
    display: flex;
    justify-content: center;
    align-items: center;
    border: 4px solid black;
    border-radius: 16px;
}
.elem.disabled {
    color: gray;
    background-color: lightgray;
    border-color: gray;
}
.elem.itsMe {
    border-color: green;
    outline: 5px solid green;
}
.value {
    width: 100%; 
}
</style>