import { logger } from './tch-dependencies'
import type { ProxyContext } from './tch-dependencies'

export function makeCsListener() {
    interface CsMainListener {
        setAliasOnEdit(alias: string): void;
        clearAlias(): void;
        tagClick(id: string, value: string): void;
    }

    let log = logger.make("cs");

    function setAliasOnEdit(alias: string) {
        log.info(_=>_({alias}));
    }

    function clearAlias() {
        log.info(_=>_());
    }

    function tagClick(id: string, value: string) {
        log.info(_=>_({id, value}));
    }

    return {
        setAliasOnEdit,
        clearAlias,
        tagClick,
    } satisfies CsMainListener;
}