import { SvelteMap } from "svelte/reactivity";
import { logger } from '../misc/logger.svelte'
import { helpers } from '../misc/helpers.svelte'

type Severity = "success" | "info" | "warning" | "error"

export interface Toast {
    id: number;
    severity: Severity;
    msg: string;
}

interface Toasts {
    get all(): SvelteMap<number, Toast>;
    push(msg: string, options?: {
        severity?: Severity,
        timeout?: number,
    }): void;
    success(msg: string): void;
    info(msg: string): void;
    warning(msg: string): void;
    error(msg: string): void;
}

export function makeToasts() {
    let log = logger.make("toasts");

    let all = new SvelteMap<number, Toast>();
    let count = 0;

    type PushOptions = Parameters<Toasts["push"]>[1];

    function push(msg: string, options?: PushOptions) {
        let args = helpers.applyDefaults(options, {
            severity: "info",
            timeout: 2000,
        });

        let toast = {
            id: count++,
            severity: args.severity,
            msg,
        } satisfies Toast;

        log.info(_=>_(toast));

        all.set(toast.id, toast);

        setTimeout(() => all.delete(toast.id), args.timeout);
    }

    return {
        get all() { return all; },
        push,
        success: msg => push(msg, {severity: "success", timeout: 2000}),
        info: msg => push(msg, {severity: "info", timeout: 2000}),
        warning: msg => push(msg, {severity: "warning", timeout: 3000}),
        error: msg => push(msg, {severity: "error", timeout: 3000}),
    } satisfies Toasts;
}