<script lang="ts">
    import type { Snippet } from "svelte";
    import { logger } from "../misc/logger.svelte";

    interface Props {
        value: string;
        children: Snippet;
        beforeEdit?: () => void;
        afterEdit?: () => void;
    }

    let {
        value = $bindable(),
        children,
        beforeEdit,
        afterEdit
    }: Props = $props();

    let input: HTMLInputElement;
    let div: HTMLDivElement;

    let focused = $state(false);
    let valueBeforeEdit = "";

    let log = logger.make("ui");

    function focus(evt: MouseEvent) {
        evt.preventDefault();
        beforeEdit?.();
        valueBeforeEdit = value;
        input.focus();
        focused = true;
    }

    function blur() {
        afterEdit?.();
        focused = false;
    }

    function keydown(evt: KeyboardEvent) {
        if (evt.key === "Enter") {
            evt.preventDefault();
            input.blur();
        }
        if (evt.key === "Escape") {
            value = valueBeforeEdit;
            input.blur();
        }
        log.trace(_=>_({key: evt.key, value}));
    }

    function edit(evt: MouseEvent) {
        evt.stopPropagation();
        focus(evt);
    }
</script>

<!-- svelte-ignore a11y_no_static_element_interactions -->
<div 
    class="container"
    class:focused
    oncontextmenu = {focus}
    bind:this = {div}
>
    {@render children()}

    <div class="edit-icon tooltip tooltip-bottom tooltip-end" data-tip={value}>
        <svg onclick={edit}
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 32 32"
            width="100%"
            height="100%"
            fill="none"
            aria-hidden="true">
            <path
                d="M6 26l2-8L21 5a3 3 0 0 1 4 0l2 2a3 3 0 0 1 0 4L14 24l-8 2z"
                stroke="currentColor"
                stroke-width="2.5"
                stroke-linecap="round"
                stroke-linejoin="round"
            />
            <path
                d="M19 7l6 6M8 18l6 6"
                stroke="currentColor"
                stroke-width="2.5"
            />
        </svg>
    </div>

    <input
        bind:this={input}
        bind:value
        onblur={blur}
        onkeydown={keydown}
        type="text"
        autocomplete="off"
        aria-label="Text input"
        enterkeyhint="go"
    />
</div>

<style>
    .container {
        position: relative;
        width: 100%;
        height: 100%;
        user-select: none;
        -webkit-user-select: none;
        -webkit-touch-callout: none;
        overflow: visible;
    }

    .focused {
        border-radius: 16px;
        box-shadow: inset 0 0 0 16px black;
    }

    input {
        position: absolute;
        inset: 0;
        padding: 0;
        border: 0;
        color: transparent;
        caret-color: transparent;
        font-size: 16px;
        pointer-events: none;
    }

    input:focus {
        outline: none;
    }

    .edit-icon {
        height: 50%;
        position: absolute;
        right: 2%;
        bottom: 10%;
        z-index: 2;
        cursor: pointer;
        overflow: visible;
    }
</style>
