import {debounce} from 'lodash';

import * as Ably from 'ably'

import {logger} from './logger.svelte';
import {assert} from './assert'
import {helpers} from './helpers.svelte'

import type {Browser} from './browser'

import type {
    IAmAStudent, IAmHere, CsProtocol, IAmATeacher 
} from '../cs-protocol';

type ItsMyTarget = (profileId: string) => boolean;

type MsgT = keyof CsProtocol;
type OnMsg<T extends MsgT> = (msg: CsProtocol[T]) => void;
type OnMsgAny = (msg: any) => void;

type TypeAndHandler = {
    [T in MsgT]: [type: T, handler: OnMsg<T>]
}[MsgT];

type TypeAndHandlerAny = [type: string, handler: OnMsgAny];

interface MyAbly {
    get isOnline(): boolean;
    get presence(): {
        students: IAmAStudent[];
        teachers: IAmATeacher[];
    };
    present(iAmHere: IAmHere): void;
    subscribe(itsMyTarget: ItsMyTarget, ...pairs: TypeAndHandler[]): void;
    subscribeAny(itsMyTarget: ItsMyTarget, ...pairs: TypeAndHandlerAny[]): void;
    publish<T extends MsgT>(type: T, msg: CsProtocol[T], targets?: string[]): void;
    publishAny(type: string, msg: any, targets?: string[]): void;
}

export function makeAbly(browser: Browser, config: {
    deviceId: string,
    appId: string,
    classroom: string,
    key: string,
}) {
    let log = logger.make("ably");

    log.info(_=>_(config));

    let realtime: Ably.Realtime;
    let channel: Ably.RealtimeChannel;

    let students: IAmAStudent[] = [];
    let teachers: IAmATeacher[] = [];

    let online = $state(false);
    let effectTrigger = helpers.makeEffectTrigger();

    connect();

    function connect() {
        let status = (status: Ably.ConnectionStateChange) => {
            let reason = status.reason ? `: ${status.reason}`: ""; 
            log.info(_=>_(`${status.current}${reason}`));
        }

        realtime = new Ably.Realtime({
            key: config.key,
            clientId: config.deviceId
        });

        let channelId = `cs:${config.classroom}`;

        realtime.connection.on(status);
        channel = realtime.channels.get(channelId);

        channel.presence.subscribe(debounce(
            () => readPresence(), 
            50, {maxWait: 200})
        );

        browser.onBackFromCache(() => {
            log.info(_=>_("back-from-cache"));
            realtime.connection.connect();
        });

        online = true;

        log.info(_=>_(`connected to ${channelId}`));
    }

    function presence() {
        effectTrigger.registerDependency();
        return { students, teachers }
    }

    async function present(iAmHere: IAmHere) {
        assert(() => channel !== undefined);

        await channel.presence.enter(iAmHere)
            .catch(e => console.log(e));

        log.info(_=>_("enter", iAmHere));
    }

    async function readPresence() {
        let members = await channel.presence.get();

        effectTrigger.raise();

        students = [];
        teachers = [];

        if (members.length === 0) {
            log.info(_=>_("no one is there"));
            return;
        }

        // assume: presence = application

        let apps = new Map<string, Ably.PresenceMessage>();

        for (let member of members) {
            let iAmHere = member.data as IAmHere;   // todo: validate shema
            log.trace(_=>_(iAmHere));

            let prev = apps.get(iAmHere.appId);

            if (prev && prev.timestamp > member.timestamp)
                continue;

            apps.set(iAmHere.appId, member);
        }

        apps.forEach(app => {
            let iAmHere = app.data as IAmHere;
            switch (iAmHere.role) {
                case "student": students.push(iAmHere); break;
                case "teacher": teachers.push(iAmHere); break;

                default:
                    iAmHere satisfies never;
                    log.error(_=>_(iAmHere));
                    break;
            }
        });

        log.info(_=>_({students, teachers}));
    }

    interface Envelope {
        targets: string[];
        msg: object;
        type: string;
    } 

    async function subscribe(itsMyTarget: ItsMyTarget, ...pairs: TypeAndHandlerAny[]) {
        assert(() => channel !== undefined);

        function handle(env: Envelope, act: OnMsgAny, ablyMsg: unknown) {
            log.trace(_=>_(env, ablyMsg));
            
            let itsForMe = 
                env.targets.length === 0 || 
                env.targets.findIndex(target => itsMyTarget(target)) >= 0;

            if (!itsForMe)
                return;

            log.info(_=>_({type: env.type, env, ablyMsg, act}));

            act(env.msg);
        }

        for (let [type, handler] of pairs) {
            log.trace(_=>_({type, handler}));
            await channel.subscribe(type, abliMsg => {
                handle(abliMsg.data, handler, abliMsg);
            });
        };
    }

    let publishToChannel = async function(type: string, env: Envelope) {
        assert(() => channel !== undefined);

        await channel.publish(type, env)
            .catch(er => console.log(er));

        log.info(_=>_({type, msg: env.msg, env}));
    }

    function publish<T extends MsgT>(type: T, msg: CsProtocol[T], targets?: string[]) {
        publishToChannel(type, {
            type,
            targets: targets ? targets : [],
            msg
        });
    }

    return {
        get isOnline() { return online; },
        get presence() { return presence() },
        present,
        subscribe: subscribe as MyAbly["subscribe"],
        subscribeAny: subscribe as MyAbly["subscribeAny"],
        publish,
        publishAny: publish as MyAbly["publishAny"],
    } satisfies MyAbly;
}