import { helpers } from './helpers.svelte'

type GroupId = "self-student";

export interface CsGroups {
    itsMyGroup(groupId: GroupId, elem: string): boolean;
    get(groupId: GroupId): string[];
    set(groupId: GroupId, elems: string[]): void;
    add(groupId: GroupId, elems: string[]): void;
    remove(groupId: GroupId, elems: string[]): void;
    replace(groupId: GroupId, elemsToRemove: string[], elemsToAdd: string[]): void;
}

export function makeGroups() {
    let groups = new Map<GroupId, Set<string>>();

    function getOrInsert(groupId: GroupId) { 
        return helpers.getOrInsert(groups, groupId, () => {
            return new Set<string>()
        });
    }

    function itsMyGroup(groupId: GroupId, elem: string) {
        let group = getOrInsert(groupId);
        return group.has(elem);
    }

    function get(groupId: GroupId) {
        if (!groups.has(groupId))
            return [];

        let group = getOrInsert(groupId);
        return [...group.values()];
    }

    function set(groupId: GroupId, elems: string[]) {
        let group = getOrInsert(groupId);
        group.clear();
        elems.forEach(elem => group.add(elem));
    }

    function add(groupId: GroupId, elems: string[]) {
        let group = getOrInsert(groupId);
        elems.forEach(elem => group.add(elem));
    }

    function remove(groupId: GroupId, elems: string[]) {
        if (!groups.has(groupId))
            return;

        let group = getOrInsert(groupId);
        elems.forEach(elem => group.delete(elem));
    }

    function replace(groupId: GroupId, elemsToRemove: string[], elemsToAdd: string[]) {
        let group = getOrInsert(groupId);
        elemsToRemove.forEach(elem => group.delete(elem));
        elemsToAdd.forEach(elem => group.add(elem));
    }

    return {
        itsMyGroup,
        get,
        set,
        add,
        remove,
        replace,
    } as CsGroups;
}