import { logger } from './logger.svelte'
import { type Firebase } from './firebase.svelte'

interface Poll {
    question: string;
    answers: string[];
    startedAt: number;
    duration: number;
}

type OnPoll = (poll: Poll) => void;

interface ShareClassroomState {
    read(classroom: string, act: OnPoll): void;
    write(classroom: string, poll: Poll): void;
} 

export function makeSharedClassroomState(firebase: Firebase) {
    let log = logger.make("classroom-state");

    let pathTo = (classroom: string) =>
        `shared/classrooms/${classroom}/poll`; 

    let isExpired = (poll: Poll, now: number) =>
        now - poll.startedAt > poll.duration;

    function read(classroom: string, act: OnPoll) {
        let now = Date.now();
        let path = pathTo(classroom);

        firebase.read<Poll>(path, poll => {
            if (isExpired(poll, now)) return;

            log.info(_=>_({path, poll}));
            act(poll);
        });
    }

    async function write(classroom: string, poll: Poll) {
        let path = pathTo(classroom);
        log.info(_=>_({path, poll}));

        await firebase.write(path, poll);
    }

    return {
        read,
        write,
    } satisfies ShareClassroomState;
}