<script lang="ts">
    import ToastsBox from '../../ui/ToastsBox.svelte'
    import Student from "./Student.svelte";

    import type { ClassroomUi } from '../tch-dependencies'    
    import { } from '../tch-dependencies'

    interface Props {
        ui: ClassroomUi,
    }

    let { ui }: Props = $props();
    let { classroom, toasts } = $derived(ui);

    $effect(() => classroom.iAmHere.send());
    $effect(() => classroom.syncWithOnline());
    $effect(() => ui.syncWithClassroom());
</script>

<div class="grid">
    {#each ui.students.values() as stu}
        <Student {ui} {stu} />
        <ToastsBox daisyUi="toast-bottom toast-end" toasts={toasts.all}/>
    {/each}
</div>

<style>
    /*- room ----------------------------------------------*/    
    .grid {
        display: grid;
        grid-template-columns: repeat(
            auto-fit,
            minmax(min(240px, 100%), 280px)
        );
        justify-content: left;
        gap: 10px;
    }
</style>
