import { parse } from 'yaml';
import { logger } from '../misc/logger.svelte'
import { helpers, type CsFirebase, type CsToasts } from './sch-dependencies';

interface Attribute {
    daisy: string;
}

interface StrAttribute extends Attribute {
    tailwind: string;
    value: string;
}

interface NumAttribute extends Attribute {
    tailwind: string;
    value: number;
}

interface TagsAttribute extends Attribute {
    values: string[];
    tailwinds: string[];
}

interface CounterAttribute extends Attribute {
    value: number;
    tailwind: string;
    id: string;
}

export type NumOrStr = StrAttribute | NumAttribute

export type SchLesson = {
    iAmIn: boolean;
    counter: CounterAttribute;
    courseId: string;
    courseName: StrAttribute;
    tags: TagsAttribute;
    topic: StrAttribute;
    date: StrAttribute;
    time: StrAttribute;
    whatsapp: string;
    whatsappAura: boolean;
}

type AllLessons = Record<string, SchLesson[]>;

export interface SchSchedule {
    get lessons(): SchLesson[];
    load(yaml: string): void;
    pushToDb(): void;
}

export function makeSchedule(firebase: CsFirebase, toasts: CsToasts) {
    let log = logger.make("schedule");

    let production = location.hostname !== 'localhost';
    let dbPath = `gebemot-school/sch-schedule`;

    let lessonsInDb: SchLesson[] = [];
    let lessons: SchLesson[] = $state([]);
    
    log.info(_=>_({production, dbPath}));

    if (production) {
        log.info(_=>_("Production is listening for schedule change..."));
        firebase.on<SchLesson[]>(dbPath, data => {
            log.info(_=>_({production, dbPath, data}));
            lessonsInDb = data;
        })
    }

    setInterval(() => setActiveLessons(), 3_000);

    function setActiveLessons() {
        let today = new Date();
        lessons = lessonsInDb.filter(
            lesson => !past(lesson.date.value, today));
    }

    function load(yaml: string) {
        let parsed: AllLessons = parse(yaml, { 
            merge: true,
            maxAliasCount: 10000,
        });

        let loaded = Object.values(parsed.lessons).flat();
        log.info(_=>_(loaded));

        lessonsInDb = loaded;
        setActiveLessons();
    }

    function pushToDb() {
        log.info(_=>_());
        firebase.write(dbPath, lessonsInDb);
        toasts.push(`Stored to ${dbPath}`);
    }

    function past(ddmm: string, now: Date) {
        let [dd, mm] = ddmm.split("/").map(Number);
        let mm2 = now.getMonth() + 1;
        let dd2 = now.getDate();

        if (mm === 12 && mm2 === 1)
            return true;

        return mm === mm2 ? 
            dd < dd2 : 
            mm < mm2;
    }

    return {
        get lessons() { return lessons; },
        load,
        pushToDb,
    } satisfies SchSchedule;
} 