import type { CsFirebase, CsProfile } from './cs-dependencies'
import { logger, config } from './cs-dependencies'

interface Details {
    at?: string; 
    classroom?: string;
    deviceId?: string;
}

interface LentaEvent {
    "enter": {
        version: string;
        alias: string;
    } & Details,
    "hello": {} & Details,
    "set-alias": {
        alias: string;
    } & Details,
    "answer": {
        value: string;
    } & Details,
}

type EventName = keyof LentaEvent;
type GetSuffix = () => string;

interface CsLenta {
    _push<T extends EventName>(event: EventName, details: LentaEvent[T], getSuffix?: GetSuffix): void;
    push<T extends EventName>(event: EventName, details: LentaEvent[T], getSuffix?: GetSuffix): void;
}

export function makeLenta(
    classroom: string,
    profile: CsProfile,
    firebase: CsFirebase,
): CsLenta {
    let log = logger.make("lenta");

    let domain = location.hostname
        .toLowerCase()
        .replaceAll('.', '-');

    log.info(_=>_({classroom}));

    let pad = (value: number, len = 2) => String(value).padStart(len, "0");

    function fmtnow(now: Date) {
        return [
            pad(now.getFullYear() % 100),
            pad(now.getMonth() + 1),
            pad(now.getDate()),
            "-",
            pad(now.getHours()),
            pad(now.getMinutes()),
            pad(now.getSeconds())
        ].join("");
    }

    function fmtnow_short(now: Date) {
        let pad = (value: number) => String(value).padStart(2, "0");
        return [
            pad(now.getMonth() + 1),
            pad(now.getDate()),
            "-",
            pad(now.getHours()),    
            pad(now.getMinutes()),
        ].join("");
    }

    function makeSuffix(getSuffix?: GetSuffix) {
        let suffix = getSuffix?.();

        if (!suffix) return "";

        suffix = suffix
            .toLocaleLowerCase()
            .replace(/[\s/.@$\[\]#]+/g, "-");

        if (!suffix.startsWith('-'))
            suffix = '-' + suffix;

        return suffix;
    }

    async function _push<T extends EventName>(event: string, details: LentaEvent[T], getSuffix?: GetSuffix) {
        let now = new Date();
        let tm = fmtnow(now);
        let codename = profile.codename;
        let deviceId = config.deviceId.replaceAll('.', '');
        let millis = `${pad(now.getUTCMilliseconds(), 3)}`
        let suffix = makeSuffix(getSuffix);

        let path = `${domain}/lenta/${codename}-${deviceId}/${tm}-${event}-${millis}${suffix}`;

        details.at = fmtnow(now);
        details.classroom = classroom;
        details.deviceId = config.deviceId;

        await firebase.write(path, details);
    }

    async function push<T extends EventName>(event: string, details: LentaEvent[T], getSuffix?: GetSuffix) {
        let now = new Date();
        let tm = fmtnow(now);
        let codename = profile.codename;
        let deviceId = config.deviceId.replaceAll('.', '');
        let millis = `${pad(now.getUTCMilliseconds(), 3)}`
        let suffix = makeSuffix(getSuffix);

        let path = `domains/${domain}/students/${codename}-${deviceId}/lenta`;
        let id = `${tm}-${event}-${millis}${suffix}`;
        log.info(_=>_({path, id}));

        details.at = fmtnow(now);
        details.classroom = classroom;
        details.deviceId = config.deviceId;

        await firebase.writeDoc(path, id, details);
    }

    return {
        _push,
        push,
    } satisfies CsLenta;
}