<script lang="ts">
    import { theme } from '../../misc/theme.svelte'
    import type { StudentUi, AddOrRemove } from '../tch-classroom-ui.svelte'    

    interface Props {
        stu: StudentUi;
    }

    let { stu } : Props = $props();
    let { hints, removes, adds } = $derived(stu);

    function itemClicked(text: string, plus: boolean) {
        console.log({text, plus});
        let dropdown: HTMLElement = <any> document.activeElement; 
        dropdown?.blur();
    }
</script>

