    {@const {plusColor, minusColor, act, values} = items}
    {#each items.values as item}
        {@const {text, weight, plus} = item}
        {@const pm = plus ? "plus" : "minus"}
        <li class="item"
            onclick={() => itemClicked(text, plus)} 
            style:--hoverColor={plus ? plusColor : minusColor}
        >
            <span class="plus-minus">
                <i class="fa-solid fa-{pm}"></i>
            </span>
            <span  class="plus-minus"
                style:font-weight={weight}
            >
                {text}
            </span>
        </li>
    {/each}
{/snippet}

<div class="dropdown dropdown-bottom">
