<script lang="ts" module>
    interface LoginDialog {
        showModal(): void;
    }

    declare var loginDialog: LoginDialog;
</script>

<script lang="ts">
    import { VERSION } from '../version';
    import { config } from '../misc/config.svelte'

    interface Props {
        id: string;
        nextWeek: boolean;
        goToNextWeek: () => void;
        goToPrevWeek: () => void;
    }

    let { id, nextWeek, goToNextWeek, goToPrevWeek }: Props = $props();

    let dev = $state(config.dev);

    function _nextWeek() {
        loginDialog.showModal();
    }
</script>

{#if dev}
    <span>{id}</span>
    &nbsp;&nbsp;&nbsp;

    <span class="text-xs"><i>{VERSION}</i></span>
{/if}

&nbsp;&nbsp;&nbsp;

{#snippet SwitchBtn(clazz: string, title: string)}
    <button class={clazz}
        onclick={() => goToPrevWeek()}
    >
        שבוע קודם
    </button>
{/snippet}

{#if nextWeek}
    <button class="btn-info btn-outline"
        onclick={() => goToPrevWeek()}
    >
        שבוע קודם
    </button>

    &nbsp;&nbsp;&nbsp;

    <button class="btn btn-info" 
        onclick={() => {}}
    >
        שבוע הבא
    </button>
{:else}
    <button class="btn btn-info"
        onclick={() => {}}
    >
        שבוע קודם
    </button>

    &nbsp;&nbsp;&nbsp;

    <button class="btn btn-info btn-outline" 
        onclick={() => goToNextWeek()}
    >
        שבוע הבא
    </button>
{/if}


<!-- Open the modal using ID.showModal() method -->
<dialog id="loginDialog" class="modal">
    <div class="modal-box">
        <h3 class="text-lg font-bold">Hello!</h3>
        <p class="py-4">Press ESC key or click outside to close</p>
    </div>
    <form method="dialog" class="modal-backdrop">
        <button>close</button>
    </form>
</dialog>
