import _ from 'lodash';

interface PointPosition {
    x: number;
    y: number;
}

interface FloatingPath {
    controlX1: number;
    controlX2: number;
    endX: number;
    speedDirection: -1 | 1;
}

interface CompanionVariation {
    startX?: number;
    startY?: number;
    controlX1?: number;
    controlX2?: number;
    endX?: number;
    endY?: number;
}

interface PointGainOptions {
    points: number;
    showPlus: boolean;
    suffix: string;
    duration: number;
    delay: number;
    height: number;
    horizontalRange: number;
    animateColor: boolean;
    color: string;
    colors: string[];
    fontSize: number;
    fontFamily: string;
    fontWeight: number;
    endScale: number;
    animateSpeed: boolean;
    speedVariation: number;
    showStars: boolean;
    starCountMin: number;
    starCountMax: number;
    starSize: number;
    starSpread: number;
    starRotations: number;
    starColors: string[];
    showHearts: boolean;
    heartCountMin: number;
    heartCountMax: number;
    heartSize: number;
    heartSpread: number;
    heartRotations: number;
    heartColors: string[];
}

type PointGainOverrides = Partial<Omit<PointGainOptions, "points">>;

export function animatePoints(
    element: HTMLElement,
    points: number,
    options: PointGainOverrides
): Animation {
    while (options === gainPreset.random) {
        options = _.sample(Object.values(gainPreset))!;
    }
    return floatPoints(element, {
        ...options,
        points
    });
}

