function floatPoints(
    startElement: HTMLElement,
    options: PointGainOverrides & { points: number }
): Animation {
    const settings: PointGainOptions = {
        points: options.points,

        showPlus: options.showPlus ?? true,
        suffix: options.suffix ?? "",

        duration: options.duration ?? 5200,
        delay: options.delay ?? 0,
        height: options.height ?? 520,
        horizontalRange:
            options.horizontalRange ?? 140,

        animateColor:
            options.animateColor ?? true,
        color: options.color ?? "#d19b2a",
        colors: options.colors ?? [
            "#ffe98a",
            "#eab52c",
            "#fff1ad"
        ],

        fontSize: options.fontSize ?? 50,
        fontFamily:
            options.fontFamily ??
            "Segoe UI, Helvetica Neue, Arial, sans-serif",
        fontWeight: options.fontWeight ?? 600,
        endScale: options.endScale ?? 0.5,

        animateSpeed:
            options.animateSpeed ?? true,
        speedVariation: Math.min(
            Math.max(
                options.speedVariation ?? 0.7,
                0
            ),
            0.95
        ),

        showStars: options.showStars ?? true,
        starCountMin: options.starCountMin ?? 3,
        starCountMax: options.starCountMax ?? 5,
        starSize: options.starSize ?? 14,
        starSpread: options.starSpread ?? 30,
        starRotations: options.starRotations ?? 2,
        starColors: options.starColors ?? [
            "#ffe47a",
            "#ffffff",
            "#9edcff",
            "#e5a4ff"
        ],

        showHearts: options.showHearts ?? true,
        heartCountMin: options.heartCountMin ?? 2,
        heartCountMax: options.heartCountMax ?? 4,
        heartSize: options.heartSize ?? 13,
        heartSpread: options.heartSpread ?? 34,
        heartRotations:
            options.heartRotations ?? 1.4,
        heartColors: options.heartColors ?? [
            "#ffd0d8",
            "#ff9aaa",
            "#ff657e",
            "#e63956",
            "#bd1738",
            "#ff4967"
        ]
    };

    const rect = startElement.getBoundingClientRect();

    const start = {
        x: rect.left + rect.width / 2,
        y: rect.top + rect.height / 2
    };

    const floatingElement =
        document.createElement("div");

    floatingElement.textContent = formatPoints(
        settings.points,
        settings
    );

    applyPointStyle(
        floatingElement,
        start,
        settings
    );

    document.body.append(floatingElement);

    const path = createRandomUpwardPath(settings);

    const keyframes = createPointKeyframes(
        path,
        settings
    );

    const animation = floatingElement.animate(
        keyframes,
        {
            duration: settings.duration,
            delay: settings.delay,
            easing: "linear",
            fill: "both"
        }
    );

    countDownPoints(
        floatingElement,
        settings,
        path
    );

    if (settings.showStars) {
        createSurroundingStars(
            start,
            path,
            settings
        );
    }

    if (settings.showHearts) {
        createSurroundingHearts(
            start,
            path,
            settings
        );
    }

    animation.finished
        .then(() => floatingElement.remove())
        .catch(() => floatingElement.remove());

    return animation;
}

function applyFloatingStyle(
    element: HTMLElement,
    start: PointPosition
): void {
    Object.assign(element.style, {
        position: "fixed",
        left: `${start.x}px`,
        top: `${start.y}px`,
        zIndex: "10000",
        pointerEvents: "none",
        userSelect: "none",
        whiteSpace: "nowrap",
        willChange: "transform, opacity, color"
    });
}

function applyPointStyle(
    element: HTMLElement,
    start: PointPosition,
    settings: PointGainOptions
): void {
    applyFloatingStyle(element, start);

    Object.assign(element.style, {
        color: settings.color,
        fontSize: `${settings.fontSize}px`,
        fontFamily: settings.fontFamily,
        fontWeight: settings.fontWeight.toString(),
        fontVariantNumeric: "tabular-nums",
        lineHeight: "1",
        filter: "drop-shadow(0 2px 2px #0005)"
    });
}

function applyCompanionStyle(
    element: HTMLElement,
    start: PointPosition,
    fontSize: number
): void {
    applyFloatingStyle(element, start);

    Object.assign(element.style, {
        fontSize: `${fontSize}px`,
        lineHeight: "1",
        opacity: "0.65",
        filter: "drop-shadow(0 0 3px currentColor)"
    });
}

function formatPoints(
    points: number,
    settings: Pick<PointGainOptions, "showPlus" | "suffix">
): string {
    const plus = settings.showPlus ? "+" : "";

    return `${plus}${points}${settings.suffix}`;
}

function cubicBezier(
    p0: number,
    p1: number,
    p2: number,
    p3: number,
    t: number
): number {
    const inverse = 1 - t;

    return (
        inverse * inverse * inverse * p0 +
        3 * inverse * inverse * t * p1 +
        3 * inverse * t * t * p2 +
        t * t * t * p3
    );
}

function createRandomUpwardPath(
    settings: Pick<PointGainOptions, "horizontalRange">
): FloatingPath {
    const range = settings.horizontalRange;

    return {
        controlX1:
            (Math.random() * 2 - 1) * range,

        controlX2:
            (Math.random() * 2 - 1) * range,

        endX:
            (Math.random() * 2 - 1) *
            range *
            0.75,

        speedDirection:
            Math.random() < 0.5 ? -1 : 1
    };
}

function motionProgress(
    t: number,
    settings: Pick<PointGainOptions, "animateSpeed" | "speedVariation">,
    path: Pick<FloatingPath, "speedDirection">
): number {
    if (!settings.animateSpeed) {
        return t;
    }

    const amount =
        settings.speedVariation *
        path.speedDirection;

    return (
        t +
        amount *
        Math.sin(Math.PI * 2 * t) /
        (Math.PI * 2)
    );
}

function positionOnPath(
    t: number,
    path: FloatingPath,
    settings: Pick<PointGainOptions, "animateSpeed" | "speedVariation" | "height">,
    variation: CompanionVariation = {}
): PointPosition {
    const progress = motionProgress(
        t,
        settings,
        path
    );

    const x = cubicBezier(
        variation.startX ?? 0,

        path.controlX1 +
        (variation.controlX1 ?? 0),

        path.controlX2 +
        (variation.controlX2 ?? 0),

        path.endX +
        (variation.endX ?? 0),

        progress
    );

    const y =
        -settings.height * progress +
        (variation.startY ?? 0) *
        (1 - progress) +
        (variation.endY ?? 0) *
        progress;

    return {
        x,
        y
    };
}

function hexToRgb(color: string): { r: number; g: number; b: number } {
    let hex = color.replace("#", "");

    if (hex.length === 3) {
        hex = hex
            .split("")
            .map(character => character + character)
            .join("");
    }

    return {
        r: parseInt(hex.slice(0, 2), 16),
        g: parseInt(hex.slice(2, 4), 16),
        b: parseInt(hex.slice(4, 6), 16)
    };
}

function interpolateColor(
    firstColor: string,
    secondColor: string,
    progress: number
): string {
    const first = hexToRgb(firstColor);
    const second = hexToRgb(secondColor);

    const r = Math.round(
        first.r +
        (second.r - first.r) * progress
    );

    const g = Math.round(
        first.g +
        (second.g - first.g) * progress
    );

    const b = Math.round(
        first.b +
        (second.b - first.b) * progress
    );

    return `rgb(${r}, ${g}, ${b})`;
}

function animatedColor(
    colors: string[],
    t: number,
    offset = 0
): string {
    if (colors.length === 0) {
        return "#000000";
    }

    if (colors.length === 1) {
        return colors[0];
    }

    const rotation =
        Math.floor(offset * colors.length) %
        colors.length;

    const rotatedColors = [
        ...colors.slice(rotation),
        ...colors.slice(0, rotation)
    ];

    const position =
        t * (rotatedColors.length - 1);

    const firstIndex = Math.floor(position);

    const secondIndex = Math.min(
        firstIndex + 1,
        rotatedColors.length - 1
    );

    const progress =
        position - firstIndex;

    return interpolateColor(
        rotatedColors[firstIndex],
        rotatedColors[secondIndex],
        progress
    );
}

function createPointKeyframes(
    path: FloatingPath,
    settings: PointGainOptions
): Keyframe[] {
    const keyframes: Keyframe[] = [];
    const frameCount = 36;

    for (let i = 0; i <= frameCount; i++) {
        const t = i / frameCount;

        const progress = motionProgress(
            t,
            settings,
            path
        );

        const position = positionOnPath(
            t,
            path,
            settings
        );

        const scale =
            1 -
            (1 - settings.endScale) *
            progress;

        const opacity = t < 0.28
            ? 1
            : 1 - (t - 0.28) / 0.72;

        const color = settings.animateColor
            ? animatedColor(settings.colors, t)
            : settings.color;

        keyframes.push({
            transform:
                `translate(-50%, -50%) ` +
                `translate(` +
                `${position.x}px, ` +
                `${position.y}px` +
                `) scale(${scale})`,

            color,
            opacity: Math.max(0, opacity),
            offset: t
        });
    }

    return keyframes;
}

function countDownPoints(
    element: HTMLElement,
    settings: PointGainOptions,
    path: FloatingPath
): void {
    let startedAt: number | undefined;

    function update(time: number) {
        if (!element.isConnected) {
            return;
        }

        if (startedAt === undefined) {
            startedAt = time;
        }

        const elapsed = time - startedAt;

        if (elapsed < settings.delay) {
            requestAnimationFrame(update);
            return;
        }

        const timeProgress = Math.min(
            (elapsed - settings.delay) /
            settings.duration,
            1
        );

        const progress = motionProgress(
            timeProgress,
            settings,
            path
        );

        const remaining = Math.max(
            0,
            Math.ceil(
                settings.points *
                (1 - progress)
            )
        );

        element.textContent = formatPoints(
            remaining,
            settings
        );

        if (timeProgress < 1) {
            requestAnimationFrame(update);
        }
    }

    requestAnimationFrame(update);
}

function randomInteger(min: number, max: number): number {
    return (
        min +
        Math.floor(
            Math.random() * (max - min + 1)
        )
    );
}

function createSurroundingStars(
    start: PointPosition,
    path: FloatingPath,
    settings: PointGainOptions
): void {
    const count = randomInteger(
        settings.starCountMin,
        settings.starCountMax
    );

    for (let i = 0; i < count; i++) {
        createStar(
            start,
            path,
            settings,
            i,
            count
        );
    }
}

function createStar(
    start: PointPosition,
    path: FloatingPath,
    settings: PointGainOptions,
    index: number,
    count: number
): void {
    const star = document.createElement("div");

    star.textContent = "\u2606";

    applyCompanionStyle(
        star,
        start,
        settings.starSize *
        (0.75 + Math.random() * 0.45)
    );

    document.body.append(star);

    const side: -1 | 1 = index % 2 === 0 ? -1 : 1;

    const variation = createCompanionVariation(
        side,
        settings.starSpread
    );

    const keyframes = createCompanionKeyframes(
        path,
        settings,
        variation,
        index,
        count,
        settings.starColors,
        settings.starRotations,
        false
    );

    const animation = star.animate(
        keyframes,
        {
            duration:
                settings.duration *
                (0.93 + Math.random() * 0.12),

            delay:
                settings.delay +
                Math.random() * 240,

            easing: "linear",
            fill: "both"
        }
    );

    animation.finished
        .then(() => star.remove())
        .catch(() => star.remove());
}

function createSurroundingHearts(
    start: PointPosition,
    path: FloatingPath,
    settings: PointGainOptions
): void {
    const count = randomInteger(
        settings.heartCountMin,
        settings.heartCountMax
    );

    for (let i = 0; i < count; i++) {
        createHeart(
            start,
            path,
            settings,
            i,
            count
        );
    }
}

function createHeart(
    start: PointPosition,
    path: FloatingPath,
    settings: PointGainOptions,
    index: number,
    count: number
): void {
    const heart = document.createElement("div");

    heart.textContent = "\u2665";

    applyCompanionStyle(
        heart,
        start,
        settings.heartSize *
        (0.75 + Math.random() * 0.45)
    );

    document.body.append(heart);

    const side: -1 | 1 = index % 2 === 0 ? 1 : -1;

    const variation = createCompanionVariation(
        side,
        settings.heartSpread
    );

    const keyframes = createCompanionKeyframes(
        path,
        settings,
        variation,
        index,
        count,
        settings.heartColors,
        settings.heartRotations,
        true
    );

    const animation = heart.animate(
        keyframes,
        {
            duration:
                settings.duration *
                (0.94 + Math.random() * 0.1),

            delay:
                settings.delay +
                80 +
                Math.random() * 260,

            easing: "linear",
            fill: "both"
        }
    );

    animation.finished
        .then(() => heart.remove())
        .catch(() => heart.remove());
}

function createCompanionVariation(
    side: -1 | 1,
    baseSpread: number
): CompanionVariation {
    const spread =
        baseSpread *
        (0.45 + Math.random() * 0.75);

    return {
        startX:
            side * spread * 0.35,

        startY:
            (Math.random() - 0.5) * spread,

        controlX1:
            side * spread *
            (0.5 + Math.random()),

        controlX2:
            side * spread *
            (0.5 + Math.random()),

        endX:
            side * spread *
            (0.5 + Math.random()),

        endY:
            (Math.random() - 0.5) *
            spread *
            1.5
    };
}

function createCompanionKeyframes(
    path: FloatingPath,
    settings: PointGainOptions,
    variation: CompanionVariation,
    index: number,
    count: number,
    colors: string[],
    rotations: number,
    heartbeat: boolean
): Keyframe[] {
    const keyframes: Keyframe[] = [];
    const frameCount = 30;

    const rotationDirection =
        index % 2 === 0 ? -1 : 1;

    const totalRotation =
        rotations *
        360 *
        rotationDirection *
        (0.75 + Math.random() * 0.5);

    const colorOffset = index / count;

    for (let i = 0; i <= frameCount; i++) {
        const t = i / frameCount;

        const position = positionOnPath(
            t,
            path,
            settings,
            variation
        );

        let opacity: number;

        if (t < 0.12) {
            opacity = t / 0.12 * 0.65;
        }
        else if (t < 0.58) {
            opacity = 0.65;
        }
        else {
            opacity =
                0.65 *
                (1 - (t - 0.58) / 0.42);
        }

        let scale: number;

        if (heartbeat && t < 0.15) {
            scale =
                0.65 +
                Math.sin(
                    t / 0.15 * Math.PI
                ) *
                0.55;
        }
        else {
            scale = 1 - t * 0.35;
        }

        const color = animatedColor(
            colors,
            t,
            colorOffset
        );

        keyframes.push({
            transform:
                `translate(-50%, -50%) ` +
                `translate(` +
                `${position.x}px, ` +
                `${position.y}px` +
                `) ` +
                `rotate(${totalRotation * t}deg) ` +
                `scale(${scale})`,

            color,
            opacity: Math.max(0, opacity),
            offset: t
        });
    }

    return keyframes;
}
