import { logger } from './logger.svelte'
import { helpers } from './helpers.svelte'

interface MyBrowser {
    copyToClipboard(text: string): void;
    readFromClipboard(): Promise<string>;
    preventLockScreen(): () => void;
    doneIf(condition: () => boolean): Promise<void>;
    onBackFromCache(act: () => void): void;
    onVisibilityChange(act: (visible: boolean) => void): void;
    onFocusChange(act: (visible: boolean) => void): void;
    onHashChange(act: (hash: string) => void): void;
    onAnyClick(act: () => void): void;
    setPageTitle(title: string): void;
    itsLikelyAMobile(): boolean;
}

export const browser = (() => {
    let log = logger.make("browser");

    let backFromCache = helpers.makeEvent();
    let visibilityChange = helpers.makeEvent<[boolean]>();
    let focusChange = helpers.makeEvent<[boolean]>();
    let hashChange = helpers.makeEvent<[string]>();
    let anyClick = helpers.makeEvent<[]>();

    listenToBackFromCache();
    listenToVisibilityChange();
    listenToFocusChange();
    listenToHashChange();
    listenToClicks();

    function listenToBackFromCache() {
        function act(evt: PageTransitionEvent) {
            log.info(_=>_({evt}));
            backFromCache.fire();
        }

        window.addEventListener("pageshow", evt => {
            if (!evt.persisted)
                return;
            act(evt);
        });
    }

    function listenToVisibilityChange() {
        function act(evt: string) {
            let visible = document.visibilityState === "visible";
            log.info(_=>_({evt, visible}));
            visibilityChange.fire(visible);
        }

        document.addEventListener("visibilitychange", () => act("visibility"));
    }

    function listenToFocusChange() {
        function act(evt: string) {
            let focused = document.hasFocus();
            log.info(_=>_({evt, focused}));
            focusChange.fire(focused);
        }

        window.addEventListener("focus", () => act("focus"));
        window.addEventListener("blur", () => act("blur"));
    }

    function listenToHashChange() {
        function act(evt: string) {
            let hash = location.hash;
            log.info(_=>_({evt, hash}));
            hashChange.fire(hash);
        }

        window.addEventListener("hashchange", () => act("hashchange"));
    }

    function listenToClicks() {
        document.addEventListener("click", () => {
            anyClick.fire();
        });
    }

    function copyToClipboard(text: string) {
        const t = document.createElement("textarea");
        t.value = text;
        document.body.appendChild(t);
        t.select();
        document.execCommand("copy");
        t.remove();
        log.info(_=>_(text));
    }

    async function readFromClipboard() {
        let text = await navigator.clipboard.readText();
        log.info(_=>_(text));
        return text;
    }

    function onBackFromCache(act: () => void) {
        backFromCache.add(act);
    }

    function preventLockScreen() {
        let wakeLock: WakeLockSentinel | null = null;
        let enabled = false;

        async function requestWakeLock() {
            try {
                wakeLock = await navigator.wakeLock.request("screen");
                enabled = true;
                log.info(_=>_("wakeLock is taken"));

                wakeLock.addEventListener("release", () => {
                    log.info(_=>_("wakeLock is released by browser"));
                    wakeLock = null;
                });
            }
            catch (er) {
                log.error(_=>_({msg: "Failed to take the lock", er}));
            }
        }

        if (wakeLock !== null)
            return () => {};

        requestWakeLock();

        document.addEventListener("visibilitychange", () => {
            if (enabled && document.visibilityState === "visible" && wakeLock === null) {
                void requestWakeLock();
            }
        });        

        return () => {
            enabled = false;
            wakeLock?.release();
            log.info(_=>_("end: wakeLock is released"));
        }
    }

    async function doneIf(condition: () => boolean) {
        let count = 0;

        while (!condition()) {
            if (count++ > 1000)
                throw new Error(`failed to resolve ${condition} (tried ${count} times)`);

            await new Promise<void>(next => {
                requestAnimationFrame(() => next());
            });
        }
    }

    function setPageTitle(title: string) {
        log.info(_=>_({title}));
        document.title = title;
    }

    function itsLikelyAMobile() {
        let ua = navigator.userAgent;

        // iPadOS sometimes identifies itself as macOS
        let isIPad =
            /iPad/i.test(ua) ||
            (navigator.platform === "MacIntel" &&
            navigator.maxTouchPoints > 1);

        if (isIPad) return false;

        let phoneUserAgent =
            /iPhone|iPod|Windows Phone/i.test(ua) ||
            (/Android/i.test(ua) && /Mobile/i.test(ua));

        let mobileClientHint =
            (<any> navigator).userAgentData?.mobile === true;

        let smallScreen =
            Math.min(screen.width, screen.height) < 500;

        let touchScreen =
            navigator.maxTouchPoints > 0 &&
            matchMedia("(pointer: coarse)").matches;

        return mobileClientHint ||
            phoneUserAgent ||
            (smallScreen && touchScreen);
    }

    return {
        copyToClipboard,
        readFromClipboard,
        preventLockScreen,
        doneIf,
        onBackFromCache: act => backFromCache.add(act),
        onVisibilityChange: act => visibilityChange.add(act),
        onFocusChange: act => focusChange.add(act),
        onHashChange: act => hashChange.add(act),
        onAnyClick: act => anyClick.add(act),
        setPageTitle,
        itsLikelyAMobile,
    } satisfies MyBrowser;
})();

export type Browser = typeof browser;