import { helpers } from "./helpers.svelte";

type Severity = "none" | "error" | "warn" | "info" | "trace";

const withAppPrefix = false;

let logsConfig = {
    "null": "none",
    "ably": "warn",
    "config": "warn",
    "profile": "warn",
    "ui": "warn",
    "classroom": "warn",
    "cs-main": "info",
    "tch-main": "info",
    "sch-main": "info",
    "browser": "warn",
    "proxy": "warn",
    "theme": "warn",
    "console": "warn",
    "cockpit": "warn",
    "id2name": "warn",
    "presence": "warn",
    "paste-parser": "info",
    "toasts": "warn",
    "firebase": "info",
    "schedule": "warn",
    "lenta": "info",
    "classroom-state": "info",
    "md-lenta": "info",
} satisfies Record<string, Severity>;

type LogName = keyof typeof logsConfig;


export type WriteToLog = (_: (...args: any[]) => void) => void;

export interface Logger {
    error(l: WriteToLog): void;
    warn(l: WriteToLog): void;
    info(l: WriteToLog): void;
    trace(l: WriteToLog): void;
}

export interface LogFactory {
    setAppId(appId: string): void;
    make(name: LogName, options?: {
        alias?: string,
        severity?: Severity,
    }): Logger;
}

let logToNull: Logger = {
    error: () => {},
    warn: () => {},
    info: () => {},
    trace: () => {},
}


export const nullLogger: LogFactory = {
    setAppId: () => {},
    make: () => logToNull,
};

export const logger = (() => {
    let appPrefix = "";

    let order: Record<Severity, number> = {
        none:  0,
        error: 1,
        warn:  2,
        info:  3,
        trace: 4
    };

    function getCallerFuncName(n: number): string | undefined {
        let stack = new Error().stack;
        if (!stack) return undefined;

        let split = stack.split("\n");
        if (split.length < 5) return undefined;

        let words = split[n].trim().split(/\s+/);
        if (words.length < 2) return undefined;

        let caller = words[1];
        let tokens = caller.split('.');

        let funcName = tokens.length > 1 ? tokens[1] : caller;
        if ([..."?=:"].some(ch => funcName.includes(ch))) return undefined;

        return funcName;
    }

    function makeLogger(name: string, logSeverity: Severity) {
        let l = new Map<Severity, string>([
            ["error", "E"],
            ["warn", "W"],
            ["info", "I"],
            ["trace", "T"],
        ]);

        let writeToNull = (...args: any[]) => {};

        function write(severity: Severity): WriteToLog {
            if (order[severity] > order[logSeverity])
                return writeToNull;

            let funcName = getCallerFuncName(4) ?? "unknown";
            let caller = funcName !== "unknown" ? `.${funcName}` : "";
            let I = l.get(severity);
            let site = `${I} [${appPrefix}${name}${caller}]`;

            switch (severity) {
                case "none": return writeToNull;
                case "error": return console.error.bind(console, site);
                case "warn": return console.warn.bind(console, site);
                case "info": return console.log.bind(console, site);
                case "trace": return console.log.bind(console, site);
                default:
                    severity satisfies never;
                    return console.log.bind(console, site);
            }
        }

        return {
            error: _ => _(write("error")),
            warn: _ => _(write("warn")),
            info: _ => _(write("info")),
            trace: _ => _(write("trace")),
        } as Logger;
    }

    function setAppId(appId: string) {
        appPrefix = withAppPrefix ? `${appId}-` : "";
    }

    type MakeOptions = Parameters<LogFactory["make"]>[1];

    function make(name: LogName, options?: MakeOptions) {
        let args = helpers.applyDefaults(options, {
            alias: "",
            severity: "info",
        });

        let severity = logsConfig[name] || args.severity;

        if (severity === "none")
            return logToNull;

        return makeLogger(args.alias || name, severity);
    }

    return {
        setAppId,
        make
    } as const satisfies LogFactory;
})();