import { logger } from './../misc/logger.svelte'

interface Id2Name {
    get names(): string[];
    get ids(): string[];
    get(id: string): string;
    addId(id: string): void;
    hasId(id: string): boolean;
    addNames(more: string[]): void;
    link(id: string, name: string): void;
    unlink(id: string): void;
    order<T>(list: T[], getName: (elem: T) => string): T[];
    clear(): void;
}

export function makeId2Name() {
    let log = logger.make("id2name");

    // stores both case and order of original inserted names
    let names = new Map<string, string>();

    let ids = new Set<string>();
    let links = new Map<string, string>();

    let lcase = (id: string) => id.toLowerCase()

    function get(id: string): string {
        let name = links.get(id);
        return name ? name : id;
    }

    function addId(id: string) {
        ids.add(id);
    }

    function hasId(id: string) {
        return ids.has(id);
    }

    function addNames(more: string[]) {
        log.info(_=>_(more));

        more.forEach(name => {
            let lname = lcase(name);
            if (names.has(lname)) {
                log.warn(_=>_(`Name '${name}' is already here, skipped`));
                return;
            }
            names.set(lname, name);
        });
    }

    function link(id: string, name: string) {
        if (!names.has(lcase(name))) {
            log.warn(_=>_(`Name '${name}' is not here (no link for id='${id}' is done`));
            return;
        }

        if (!ids.has(id)) {
            log.warn(_=>_(`Id '${id}' is not here (no link for name='${name}' is done`));
            return;
        }

        if (links.has(id)) {
            log.warn(_=>_(`Overriding link of '${id}' with '${name}'; previous='${map.get(id)}'`));
        }

        links.set(id, name);
    }

    function unlink(id: string) {
        links.delete(id);
    }

    function order<T>(list: T[], getName: (elem: T) => string): T[] {
        let lnames = [...names.keys()];
        let ordered: T[] = [];

        list.forEach(elem => {
            let name = getName(elem);
            let indx = lnames.indexOf(lcase(name));

            if (indx < 0) {
                log.info(_=>_(`'${name}' is not found within added names`));
                return;
            }

            if (ordered[indx] !== undefined) {
                log.info(_=>_(`'${name}' is already set (twice in list?)`));
                return;
            }

            ordered[indx] = elem;
        });

        return ordered;
    }

    function clear() {
        log.warn(_=>_({
            names: names.size,
            ids: ids.size,
            links: links.size,
        }));

        names.clear();
        ids.clear();
        links.clear();
    }

    return {
        get names() { return [...names.values()]; },
        get ids() { return [...ids]; },
        get,
        addId,
        hasId,
        addNames,
        link,
        unlink,
        order,
        clear,
    } satisfies Id2Name;
}
