import { isEqual } from "lodash";

import type {
    CsProtocol, CsAbly, Browser,
    CsToasts,
} from './tch-dependencies'

import {
    logger, helpers,
} from './tch-dependencies'

import { makeId2Name } from "./id2name.svelte";
import { makeIAmHere, type IAmHere } from "./tch-i-am-here.svelte";
import { makeStudent, makeOnlinePeer, type Student, type OnlinePeer } from './tch-student.svelte'
import { makePasteParser } from "./utils/paste-parser";


export interface Classroom {
    get id(): string;
    get students(): Student[];
    get iAmHere(): IAmHere;
    id2student(id: string): Student | undefined;
    syncWithOnline(): void;
    peersOf(stu: Student): string[];
    devicesOf(stu: Student): string[];
    s2tAnswer(msg: CsProtocol["s2t-answer"]): void;
    b2aPoll(msg: CsProtocol["b2a-poll"]): void;
    selected(): void;
    pasteStudents(text: string): void;
}

export function makeClassroom(appId: string, classroom: string,
    browser: Browser, 
    ably: CsAbly,
    toasts: CsToasts,
) {
    let log = logger.make("classroom", {
        alias: classroom,
    });

    let iAmHere = makeIAmHere(appId, browser, ably);
    let studentsAreHereTrigger = helpers.makeEffectTrigger();

    let id2stu = new Map<string, Student>();
    let id2name = makeId2Name();
    let parser = makePasteParser(toasts);


    function id2student(id: string) {
        return id2stu.get(id);
    }

    function peersOf(stu: Student) {
        let peers = stu.online.peers.map(peer => peer.profileId);
        return peers;
    }

    function devicesOf(stu: Student) {
        let devices = stu.online.peers.map(peer => peer.deviceId);
        return devices;
    }

    function syncWithOnline() {
        function setOnline(stu: Student, online: OnlinePeer) {
            if (isEqual(stu.online, online)) return;
            stu.online = online;
        }

        // aggregate current online state
        function buildOnlinePresence() {
            let presence = new Map<string, OnlinePeer>();
            ably.presence.students.forEach(iAmHere => {
                iAmHere.profiles.forEach(profile => {
                    let online = helpers.getOrInsert(presence, profile.profileId, 
                        () => makeOnlinePeer());

                    online.appIsVisible ||= iAmHere.appIsVisible;
                    online.appIsFocused ||= iAmHere.appIsFocused;
                    online.helloIsHere ||= profile.helloIsHere;
                    online.mobileIsHere ||= iAmHere.itsAMobile;
                    let isActive = iAmHere.appIsVisible && iAmHere.appIsFocused;

                    online.peers.push({
                        deviceId: iAmHere.deviceId,
                        appId: iAmHere.appId,
                        profileId: profile.profileId,
                        codename: profile.codename,
                        alias: profile.alias,
                        isActive,
                    });
                })
            });
            return presence;
        }

        let presence = buildOnlinePresence();

        // add new clients; set onine info only if changed
        presence.forEach((online, id) => {
             let stu = helpers.getOrInsert(id2stu, id, () => makeStudent(id));
             setOnline(stu, online);
             stu.classroom.lastSeenName = online.peers[0].alias;
        });

        // clear online info for not connected clients
        id2stu.forEach((stu, id) => {
            if (presence.has(id)) return;
            setOnline(stu, makeOnlinePeer());    // empty online state
        });

        let students = [...id2stu.values()];
        let active = students.filter(stu => stu.isActive);

        log.info(_=>_({
            online: ably.presence.students.length,
            students: students.length,
            active: active.map(stu => stu.name),
        }));

        studentsAreHereTrigger.raise();
    }

    function s2tAnswer(msg: CsProtocol["s2t-answer"]) {
        let stu = id2stu.get(msg.profileId);

        if (!stu) {
            log.warn(_=>_(`Can't find student for '${msg.profileId}'`));
            return;
        }

        log.info(_=>_(`${stu.name}: '${msg.value}'`));
        stu.studying.answer = msg.value;
    }

    function b2aPoll(msg: CsProtocol["b2a-poll"]) {
        log.info(_=>_());
        id2stu.forEach(stu => stu.studying.answer = "");
    }

    function selected() {
    }

    function getStudents() {
        studentsAreHereTrigger.registerDependency();
        return [...id2stu.values()];
    }

    function pasteStudents(text: string) {
        log.info(_=>_(text));

        function parse() {
            let names: string[][] = parser.parseStudents(text);

            if (names.length === 0) {
                toasts.warning("Text seems to be empty...");
                return;
            }

            let firstColumn = names.map(row => row[0]);
            id2name.addNames(firstColumn);

            toasts.success(`Parsed ${names.length} names`);
        }

        try {
            parse();
        } 
        catch (err: any) {
            toasts.error(err.message);
            return;
        }
    }

    return {
        get id() { return classroom; },
        get students() { return getStudents(); },
        get iAmHere() { return iAmHere; },
        id2student,
        peersOf,
        devicesOf,
        syncWithOnline,
        s2tAnswer,
        b2aPoll,
        selected,
        pasteStudents,
    } as const satisfies Classroom;
};
