<script lang="ts">
    import { config } from '../misc/config.svelte'
    import ControlHeader from './ControlHeader.svelte';
    import Lesson01 from './lessons/lesson-01.svelte';
    import Lesson02 from './lessons/lesson-02.svelte';
    import SingleCard from './SingleCard.svelte';

    import { browser } from '../misc/browser'

    let domain = location.hostname;
    browser.setPageTitle(`${domain} Lesson 02`);

    let nextWeek = $state(true); 

    function goToNextWeek() {
        nextWeek = true;
    }

    function goToPrevWeek() {
        nextWeek = false;
    }

    let id = $state(config.id);
</script>


{#if id.length > 0}
    <SingleCard {id}/>
{:else}
    <ControlHeader id="lesson-02" {nextWeek} {goToNextWeek} {goToPrevWeek}/>
    {#if nextWeek}
        <Lesson02 />
    {:else}
        <Lesson01 />
    {/if}
{/if}