import { logger, helpers } from './cs-dependencies'
import type { Browser, CsConfig, CsProfile, IAmAStudent } from './cs-dependencies'

interface CsPresence {
    get iAmHere(): IAmAStudent;
    get helloIsHere(): boolean;
    hello(here: boolean): void;
}

export function makePresence(
    appId: string,
    config: CsConfig,
    profile: CsProfile,
    browser: Browser,
) {
    let log = logger.make("presence");

    let appIsVisible = $state(document.visibilityState === "visible");
    let appIsFocused = $state(document.hasFocus());
    let helloIsHere = $state(false);
    let itsAMobile = browser.itsLikelyAMobile();
    let iAmHereTrigger = helpers.makeEffectTrigger();

    browser.onVisibilityChange(visible => appIsVisible = visible);
    browser.onFocusChange(focused => appIsFocused = focused);
    browser.onBackFromCache(() => iAmHereTrigger.raise());

    function iAmHere(): IAmAStudent {
        iAmHereTrigger.registerDependency();

        let profiles = profile.activeProfiles;

        return {
            role: "student",
            classroom: config.classroom,
            deviceId: config.deviceId,
            itsAMobile,
            appId,
            profiles,
            appIsVisible,
            appIsFocused,
        };
    } 

    function hello(here: boolean) {
        log.info(_=>_({here}));
        helloIsHere = true;
    }

    return {
        get iAmHere() { return iAmHere() },
        get helloIsHere() { return helloIsHere; },
        hello,
    } as const satisfies CsPresence;
}

