<script lang="ts">
    import { fade } from "svelte/transition";

    import { 
        logger, helpers, makeAbly, browser, makeSchedule,
        makeMain,
        VERSION
    } from './sch-dependencies'

    import type { SchLesson, SharedCounter } from './sch-dependencies'

    import ToastsBox from '../ui/ToastsBox.svelte';
    import LoginBar from "../ui/LoginBar.svelte";

    let host = location.hostname;
    browser.setPageTitle(`${host} School ${VERSION}`);

    let appId = helpers.makeId(2, "sch.");
    logger.setAppId(appId);
    let log = logger.make("sch-main");

    let sch = makeMain(appId)
    let { toasts, firebase } = sch;

    $effect(() => { sch.loadSchedule(); });

    type Attribute = {
        value: string | number;
        tailwind: string;
        daisy: string;
    }

    type Tags = {
        values: string[];
        tailwinds: string[];
    }

    type Counter = {
        value: number;
        tailwind: string;
    }

    function getLessonBgColor(indx: number) {
        let colors = [
            ["bg-blue-100", "bg-yellow-100", "bg-green-100"],
            ["bg-green-100", "bg-pink-100", "bg-indigo-100"],
        ];

        return colors[indx % 2][0]; 
    }
</script>

{#snippet attr(attr: Attribute)}
    <span class="tag kbd rounded-lg font-bold {attr.tailwind} {attr.daisy}">
        {attr.value}
    </span>
{/snippet}

{#snippet tags(attr: Tags)}
    {#each attr.values as tag, i}
        {@const tailwind = attr.tailwinds[i]}
        <span class="tag kbd rounded-lg font-bold {tailwind}">
            {tag}
        </span>
    {/each}
{/snippet}

{#snippet whatsapp(lesson: SchLesson)}
    {#if lesson.iAmIn}
    {@const aura=lesson.whatsappAura ? "aura text-orange-600" : ""}
    <div class="{aura}">
    <span class="kbd kbd-xl rounded-lg py-4 text-xl bg-purple-200"
        in:fade={{ duration: 300 }}
    >
        <a class="link link-primary" target="_blank" title=""
            href={lesson.whatsapp}
            onclick={() => lesson.whatsappAura = false}
        >
            chat.whatsapp.com/...
        </a>
    </span>
    </div>
    {/if}
{/snippet}

{#snippet iAmIn(lesson: SchLesson)}
    {@const aura = lesson.iAmIn ? "" : "aura text-orange-600"}
    <div class="{aura}">
    <div class="iAmIn">
        <input type="checkbox"
            class="toggle toggle-xl text-4xl py-4 bg-gray-200 text-black checked:bg-green-400" 
            bind:checked={
                () => sch.getEnrollment(lesson),
                yes => sch.enroll(lesson, yes)
            }
        />
    </div>
    </div>
{/snippet}

{#snippet counter(shared: SharedCounter, attr: Counter)}
    <span class="tag kbd font-bold {attr.tailwind}">
        {shared.value}
    </span>
{/snippet}

{#snippet Lesson(lesson: SchLesson, indx: number)}
    {@const shared = sch.getSharedCounter(lesson)}
    <div class="row {getLessonBgColor(indx)}">
        {@render attr(lesson.date)}
        {@render attr(lesson.time)}
        {@render attr(lesson.topic)}
        {@render attr(lesson.courseName)}
        {@render iAmIn(lesson)}
        {@render counter(shared, lesson.counter)}
        {@render tags(lesson.tags)}
        {@render whatsapp(lesson)}
    </div>
{/snippet}

{#snippet version()}
        <span class="version font-xs absolute top-0 right-2 bg-transparent text-transparent">
            <i>{VERSION}</i>
        </span>
{/snippet}

{#if sch.localhost}
    <LoginBar {firebase} push={() => sch.pushSchedule()}/>
{/if}
<div class="rows flex w-full flex-col"> 
    {@render version()}
    {#each sch.schedule.lessons as lesson, indx}
        {@render Lesson(lesson, indx)} 
    {/each}
    <ToastsBox daisyUi="toast-top toast-end" toasts={toasts.all}/>
</div>


<style>
.version:hover {
    color: gray;
}
.rows {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    row-gap: 1px;
    background-color: black;
}
.row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    column-gap: 16px;
    row-gap: 10px; 
    padding: 10px;
    width: 100%;
    height: 100%;
}
.iAmIn {
    display: inline-flex;
    align-items: center;
    column-gap: 4px;
}
.tag {
    max-width: 100%;
    height: auto;
    white-space: normal;
    overflow-wrap: break-word;
    text-align: center;
}
</style>
