<script lang="ts">
    import type { EffectTrigger } from '../misc/helpers.svelte';
    import { theme } from '../misc/theme.svelte'

    interface Area {
        id: string;
        l: number; 
        t: number; 
        w: number; 
        h: number;
    }

    interface Svg {
        id: string;
        color?: string;
        font?: string;
        fontScale?: number;
    }

    interface Section {
        id: string;
        h: number;
        color: string;
    }

    interface Layout {
        sections: Section[];
        areas: Area[];
        svgs: Svg[];
        effectTrigger: EffectTrigger;
    }

    interface Props {
        layout: Layout;
        children: any;
    }

    let { 
        layout,
        children, 
    }: Props = $props();

    let scene: HTMLDivElement;
    let slots: HTMLElement[];

    function percent(value: number) {
        return `${value}%`;
    }

    function findById(id: string) {
        return slots.find(elem => elem.id === id);
    }

    function applySection(section: Section) {
        let elem = findById(section.id);
        if (!elem) return;

        elem.style.backgroundColor = theme.map(section.color);
        elem.style.minWidth = '0';
        elem.style.minHeight = '0';
        elem.style.overflow = 'hidden';
    }

    function applyArea(area: Area) {
        let elem = findById(area.id);
        if (!elem) return;

        elem.style.left = percent(area.l);
        elem.style.top = percent(area.t);
        elem.style.width = percent(area.w);
        elem.style.height = percent(area.h);
    }

    $effect(() => {
        layout.effectTrigger.registerDependency();

        slots = Array.from(
            scene.querySelectorAll<HTMLElement>('[id]'));

        let heights = layout.sections.map(
            section => percent(section.h));

        let rows = heights.join(' ');
        scene.style.setProperty('--section-rows', rows);

        layout.sections.forEach(applySection);
        layout.areas.forEach(applyArea);
    });
    
</script>

<div class="scene" bind:this={scene}>
    {@render children()} 
</div>

<style>
    .scene {
        position: relative;
        min-height: 100dvh;
        display: grid;
        grid-template-rows: var(--section-rows);
        overflow: hidden;
        background-color: aliceblue;
    }
</style>
