<script lang="ts">
    import GLoginButton from "./GLoginButton.svelte";
    import { type Firebase } from '../misc/firebase.svelte'
    import { browser } from '../misc/browser'

    interface Props {
        firebase: Firebase;
        push: () => void;
    }

    let { firebase, push }: Props = $props();
    let { user } = $derived(firebase);
</script>

{#snippet property(value: string, tailwind: string)}
    <span class="kbd {tailwind}"
        onclick = {() => browser.copyToClipboard(value)}
    >
        {value}
    </span>
{/snippet}

{#snippet pushButton()}
    <button class="btn kbd bg-yellow-300"
        onclick={push}
    >
        Push
    </button>
{/snippet}

{#snippet signOutButton()}
    <button class="btn kbd bg-orange-300"
        onclick={() => firebase.signOut()}
    >
        Sign out
    </button>
{/snippet}

<div class="login">
    <GLoginButton {firebase} float={false} top="0px" right="10px"/>
    {#if user.signedIn} 
        {@const { uid, email, name } = user }
        {@render property(name, "text-xl bg-green-200")}
        {@render property(email, "text-xl bg-orange-100")}
        {@render property(uid, "text-sm bg-gray-100")}
        {#if firebase.user.isAdmin}
            {@render pushButton()}
        {/if}
        {@render signOutButton()}
   {/if}
</div>
