import { initializeApp } from "firebase/app";
import { getDatabase, ref, get, set, onValue, runTransaction } from "firebase/database";
import { getFirestore, collection, doc, setDoc, getDocs } from "firebase/firestore";
import { getAuth, GoogleAuthProvider, onAuthStateChanged, signInWithPopup, signOut } from "firebase/auth";

import { assert, assert2 } from './assert'
import { logger } from './logger.svelte'

export interface Firebase {
    get signedIn(): boolean;
    get user(): UserInfo;
    signIn(): void;
    signOut(): void;
    read<T>(path: string, act: (value: T) => void): void;
    on<T>(path: string, act: (value: T) => void): () => void;
    write<T>(path: string, value: T): Promise<void>;
    getSharedCounter(id: string): {
        get value(): number;
        increment(): void;
        decrement(): void;
    };
    readDoc<T extends object>(path: string, id: string, act: (value: T) => void): void;
    writeDoc<T extends object>(path: string, id: string, value: T): Promise<void>;
}

export type SharedCounter = ReturnType<Firebase["getSharedCounter"]>

export type UserInfo = {
    signedIn: boolean;
    isAdmin: boolean;
    uid: string;
    email: string;
    name: string;
}

const firebaseConfig = {
    apiKey: "AIzaSyD1T1d6L2qF2bDjHxIQaidyuKIlNPxikK0",
    authDomain: "gebemot.school",
    databaseURL: "https://gebemot-enrolment-v0-default-rtdb.europe-west1.firebasedatabase.app",
    projectId: "gebemot-enrolment-v0",
    storageBucket: "gebemot-enrolment-v0.firebasestorage.app",
    messagingSenderId: "677976152796",
    appId: "1:677976152796:web:6bf19a46934ff18ff8b219"
};

export function makeFirebase() {
    let log = logger.make("firebase");
    let app = initializeApp(firebaseConfig);
    let rtdb = getDatabase(app);
    let docdb = getFirestore(app);
    let auth = getAuth(app);

    let userInfo: UserInfo = $state({
        signedIn: false,
        isAdmin: false,
        uid: "",
        email: "",
        name: ""
    });

    let counters = new Map<string, SharedCounter>();
    let withGoogle = new GoogleAuthProvider();

    let cancelPrevAdmin: () => void;


    onAuthStateChanged(auth, user => {
        userInfo.signedIn = !!user;
        if (!user) return;

        assert2(() => !!user.email, user.email);
        assert2(() => !!user.displayName, user.displayName);

        userInfo = {
            signedIn: true,
            isAdmin: false,
            uid: user.uid,
            email: user.email,
            name: user.displayName,
        };


        let adminPath = `users/${user.uid}/admin`;
        cancelPrevAdmin?.();

        cancelPrevAdmin = onValue(ref(rtdb, adminPath), admin => {
            userInfo.isAdmin = admin.val() === true;
            log.info(_=>_({adminPath, isAdmin: admin.val()}));
        })

        log.info(_=>_(adminPath, cancelPrevAdmin, $state.snapshot(userInfo)));
    });

    function signIn() {
        log.info(_=>_());
        signInWithPopup(auth, withGoogle);
    }

    function _signOut() {
        log.info(_=>_());
        signOut(auth);
    }

    function makeSharedCounter(id: string) {
        let value = $state(0);
        let domain = location.hostname.replaceAll('.', '-');

        let path = `shared/counters/${domain}/${id}/value`;
        let counterRef = ref(rtdb, path);

        onValue(counterRef, snapshot => {
            let x = snapshot.val() ?? 0;
            value = x;
            log.trace(_=>_({id, value: x}));
        });        

        log.trace(_=>_({id, path}));

        async function increment() {
            await runTransaction(counterRef, x => x + 1);            
            log.info(_=>_({id}));
        }

        async function decrement() {
            await runTransaction(counterRef, x => x - 1);            
            log.info(_=>_({id}));
        }

        return {
            get value() { return value; },
            increment,
            decrement,
        } satisfies SharedCounter;
    }

    function getSharedCounter(id: string) {
        let counter = counters.get(id);
        if (counter) return counter;

        counter = makeSharedCounter(id);
        counters.set(id, counter);

        return counter;
    }

    async function read<T>(path: string, act: (value: T) => void) {
        log.info(_=>_(path));

        let snapshot = await get(ref(rtdb, path));

        if (!snapshot.exists()) {
            log.info(_=>_(`${path} doesn't have any value`));
            return;
        }

        act(snapshot.val());
    }

    function on<T>(path: string, act: (value: T) => void) {
        log.info(_=>_(path));

        let cancel = onValue(ref(rtdb, path), snapshot => {
            if (!snapshot.exists()) {
                log.info(_=>_(`${path} doesn't have any value (still not there, or just deleted)`));
                return;
            }

            let value = snapshot.val();
            log.info(_=>_({path, value}));
            act(value);
        })

        return cancel;
    }

    async function write<T>(path: string, value: T) {
        log.trace(_=>_({path, value}));
        set(ref(rtdb, path), value);
    }

    function readDoc<T extends object>(path: string, id: string, act: (value: T) => void) {

    }

    async function writeDoc<T extends object>(path: string, id: string, value: T): Promise<void> {
        log.info(_=>_({path, id, value}));
        await setDoc(doc(docdb, path, id), value);
    }


    return {
        get signedIn() { return userInfo.signedIn; },
        get user() { return userInfo; },
        signIn,
        signOut: _signOut,
        read,
        on,
        write,
        getSharedCounter,
        readDoc,
        writeDoc,
    } satisfies Firebase;
}