import { makeAbly } from './ably.svelte';
import { logger } from './logger.svelte';

type Ably = ReturnType<typeof makeAbly>;

interface ProxyFactory {
    make<T extends object>(name: string, target: T): T;
}

export interface ProxyContext {
    proxy: string;
    func: string;
} 

interface ProxyMsg extends ProxyContext {
    args: string;
}

type ItsMyTarget = (profileId: string) => boolean;
type GetProfileId = () => string;

export function makeProxyFactory(ably: Ably, 
    getProfileId: GetProfileId, 
    itsMyTarget: ItsMyTarget
) {
    let log = logger.make("proxy");
    let proxies = new Map<string, any>();

    ably.subscribeAny(itsMyTarget,
        ["_proxy_to_targets", dispatch]
    );

    function argsToJson(args: unknown[]): string {
        return JSON.stringify(args);
    }

    function jsonToArgs(json: string): unknown[] {
        return JSON.parse(json);
    }

    function publish(msg: ProxyMsg) {
        ably.publishAny("_proxy_to_targets", msg, [getProfileId()]);
    }

    function dispatch(msg: ProxyMsg): void {
        let proxy = proxies.get(msg.proxy);

        if (!proxy) {
            log.trace(_=>_(`Can't find proxy for '${msg.proxy}' (func=${msg.func})`));
            return;
        }

        let args = jsonToArgs(msg.args);
        log.trace(_=>_({func: msg.func, msg, args}));

        args.push(msg);

        proxy[msg.func](...args);
    }

    function make(name: string, target: any): any {
        log.trace(_=>_(`Registering proxy for '${name}'`));

        if (proxies.has(target))
            log.warn(_=>_(`Proxy '${target}' is alredy registered (overriding)`));

        proxies.set(name, target);

        let proxy = new Proxy({}, {
            get(_, property) {
                return (...args: unknown[]) => {
                    let json = argsToJson(args);
                    publish({
                        proxy: name,
                        func: String(property),
                        args: json
                }   );
                }
            }
        });

        return proxy;
    }

    return {
        make: make as ProxyFactory["make"],
    } satisfies ProxyFactory;
}